# time for column c (c>=6): 08:00 + (c-6)*15 min, as fraction of day
def col_time(c):
    return (8*60 + (c-6)*15)/1440.0

def blocks(row):
    res=[]
    start=None
    for c in range(6, ws.max_column+1):
        v = ws.cell(row=row, column=c).value
        if v=='m':
            if start is None:
                start=c
            end=c
        else:
            if start is not None:
                res.append((start,end))
                start=None
    if start is not None:
        res.append((start,end))
